            VirtualKey.F10 => "\x1b[21~",
            VirtualKey.F11 => "\x1b[23~",
            VirtualKey.F12 => "\x1b[24~",
            _ => null,
        };
        if (seq is not null) { Send(seq); e.Handled = true; }
